@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService Alerts
@implements IDisposable

<PageTitle>Dashboard – @Warehouse.CurrentWarehouseName</PageTitle>

<h1>Dashboard</h1>
<p class="text-muted">Viewing: <strong>@Warehouse.CurrentWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @if (Alerts.CurrentAlertCount > 0)
            {
                <span class="text-danger">@Alerts.CurrentAlertCount</span>
            }
            else
            {
                <span class="text-success">0</span>
            }
        </p>
        <p class="text-muted mb-0">
            Polling every 10 seconds&ensp;
            @if (_isPolling)
            {
                <span class="spinner-border spinner-border-sm" role="status"></span>
            }
        </p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private bool _isPolling;

    protected override void OnInitialized()
    {
        // Re-render when the warehouse changes so the heading updates.
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            StateHasChanged();
            // Immediately poll for the new warehouse's alerts.
            await PollOnceAsync();
        });
        Warehouse.OnChange += _warehouseHandler;

        // Re-render when alert data arrives (keeps this page in sync
        // even though AlertBadge also subscribes independently).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        Alerts.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Kick off polling when the dashboard becomes visible.
            _cts = new CancellationTokenSource();
            await PollOnceAsync();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (await timer.WaitForNextTickAsync(ct))
        {
            await PollOnceAsync();
        }
    }

    private async Task PollOnceAsync()
    {
        _isPolling = true;
        await InvokeAsync(StateHasChanged);

        var count = await Alerts.GetLowStockCountAsync(Warehouse.CurrentWarehouseId);

        // UpdateAlertCount fires OnAlertCountChanged, which notifies
        // BOTH this page AND the sidebar AlertBadge.
        Alerts.UpdateAlertCount(count);

        _isPolling = false;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        Warehouse.OnChange -= _warehouseHandler;
        Alerts.OnAlertCountChanged -= _alertHandler;
    }
}

